#include <bits/stdc++.h>
using namespace std;

#define int int64_t

signed main() {
	// your code goes here
    int t;
    cin >> t;
    while(t --)
    {
        int n;
        cin >> n;
        
        int m = 3 * n;
        vector<int> a(m + 1);
        for(int i = 1; i <= m; i ++)
            cin >> a[i];
            
        sort(a.begin() + 1, a.end());
        
        auto p = a;
        for(int i = 1; i <= m; i ++)
            p[i] += p[i - 1];
        auto query = [&](int l, int r) -> int
        {
            if(l > r)
                return int(0);
            return p[r] - p[l - 1];  
        };
        
        int ans = 0;
        for(int r = 0; r <= n; r ++)
        {
            int here = 0;
            int base = 6 * query(m - r + 1, m);
            auto f = [&](int q) -> int
            {
                assert(q + r <= n);
                int p = n - q - r;
                int sum = base;
                int rb = m - r;
                sum += 4 * query(rb - 2 * q + 1, rb);
                rb -= 2 * q;
                sum += 3 * query(rb - 3 * p + 1, rb);
                return sum;
            };
            
            here = max(here, f(0));
            here = max(here, f(n - r));
            
            int s = 1, e = n - r, opt = 0;
            while(s <= e)
            {
                int m = (s + e)/2;
                if(f(m) - f(m - 1) >= 0)
                    s = m + 1, opt = m;
                else
                    e = m - 1;
            };
            
            here = max(here, f(opt));
            
            ans = max(ans, here);
        }
        
        cout << ans << endl;
    }
}
